const P=await figma.getNodeByIdAsync('5:2'); await figma.setCurrentPageAsync(P);
const S={};for(const n of ['01_Aktivitas','02_Trending','03_Detail_Saham','04_Top_Up_Metode','05_Top_Up_Nominal','06_Top_Up_Pembayaran'])S[n]=P.children.find(c=>c.name===n);
const nav=(dest,anim='DISSOLVE')=>[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:S[dest].id,navigation:'NAVIGATE',transition:anim==='DISSOLVE'?{type:'DISSOLVE',duration:0.2,easing:{type:'EASE_OUT'}}:{type:'SMART_ANIMATE',duration:0.3,easing:{type:'EASE_IN_AND_OUT'}},preserveScrollPosition:false}]}];
const log=[];
const link=async(screen,pred,dest,anim)=>{const n=S[screen].findOne(pred);if(!n){log.push('MISSING '+screen);return;}await n.setReactionsAsync(nav(dest,anim));log.push(`${screen}: ${n.name} -> ${dest}`);};
const by=name=>n=>n.name===name;
await link('01_Aktivitas',n=>n.name==='Deposit'&&n.type==='INSTANCE','04_Top_Up_Metode');
for(const s of ['01_Aktivitas','02_Trending','04_Top_Up_Metode','05_Top_Up_Nominal']){
 if(s!=='01_Aktivitas')await link(s,by('Tab/Aktivitas'),'01_Aktivitas');
 if(s!=='02_Trending')await link(s,by('Tab/Trending'),'02_Trending');
 if(!s.startsWith('04'))await link(s,by('Tab/Top Up'),'04_Top_Up_Metode');}
await link('02_Trending',by('Stock Row/GOTO'),'03_Detail_Saham','SMART');
await link('03_Detail_Saham',by('Back'),'02_Trending');
await link('04_Top_Up_Metode',by('Method/Alfamart'),'05_Top_Up_Nominal');
await link('04_Top_Up_Metode',by('Back'),'01_Aktivitas');
await link('05_Top_Up_Nominal',by('Bayar'),'06_Top_Up_Pembayaran');
await link('05_Top_Up_Nominal',by('Back'),'04_Top_Up_Metode');
await link('05_Top_Up_Nominal',by('Ganti'),'04_Top_Up_Metode');
await link('06_Top_Up_Pembayaran',by('Oke'),'01_Aktivitas');
P.flowStartingPoints=[{nodeId:S['01_Aktivitas'].id,name:'Stock Trading · Main flow'}];
return {log,ids:Object.fromEntries(Object.entries(S).map(([k,v])=>[k,v.id]))};

const P=await figma.getNodeByIdAsync('5:2');const r=[];
P.findAll(n=>n.reactions&&n.reactions.length>0).forEach(n=>{let s=n;while(s.parent&&s.parent.type!=='PAGE')s=s.parent;r.push(`${s.name} | ${n.name} -> ${n.reactions[0].actions[0].destinationId}`);});
return {count:r.length,r,flow:P.flowStartingPoints,top:P.children.map(c=>`${c.name} ${c.x},${c.y} ${c.width}x${c.height}`)};

